  1938  cmsBool DataFormatSection(cmsIT8* it8)
  1939  {
  1940      int iField = 0;
  1941      TABLE* t = GetTable(it8);
  1942
  1943      InSymbol(it8);   // Eats "BEGIN_DATA_FORMAT"
  1944      CheckEOLN(it8);
  1945
  1946      while (it8->sy != SEND_DATA_FORMAT &&
  1947          it8->sy != SEOLN &&
  1948          it8->sy != SEOF &&
  1949          it8->sy != SSYNERROR)  {
  1950
  1951              if (it8->sy != SIDENT) {
  1952
  1953                  return SynError(it8, "Sample type expected");
  1954              }
  1955
  1956              if (!SetDataFormat(it8, iField, StringPtr(it8->id))) return FALSE;
  1957              iField++;
  1958
  1959              InSymbol(it8);
  1960              SkipEOLN(it8);
  1961         }
  1962
  1963         SkipEOLN(it8);
  1964         Skip(it8, SEND_DATA_FORMAT);
  1965         SkipEOLN(it8);
  1966
  1967         if (iField != t ->nSamples) {
  1968             SynError(it8, "Count mismatch. NUMBER_OF_FIELDS was %d, found %d\n", t ->nSamples, iField);
  1969
  1970
  1971         }
  1972
  1973         return TRUE;
  1974  }
